package com.forgeflow.schedulerservice.service;
import org.slf4j.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import java.util.Map;
@Component public class SchedulerLoop {private static final Logger log=LoggerFactory.getLogger(SchedulerLoop.class);private final RestClient client;private final String token;public SchedulerLoop(@Value("${app.job-service-url:http://localhost:8081}")String base,@Value("${app.internal-token:dev-internal-token}")String token){client=RestClient.builder().baseUrl(base).build();this.token=token;}@Scheduled(fixedDelayString="${app.interval-ms:2000}") public void dispatch(){try{Map<?,?> response=client.post().uri("/internal/scheduler/dispatch-due").header("X-Internal-Token",token).retrieve().body(Map.class);if(response!=null&&response.get("processed") instanceof Number n&&n.intValue()>0)log.info("Scheduler checked due jobs: {}",n.intValue());}catch(Exception ex){log.warn("Scheduler cannot reach Job Service: {}",ex.getMessage());}}}
